from typing import List, Tuple
import math

def f(N: int, M: int, pairs: List[Tuple[int, int]]):
    if M == 0:
        return N

    parent = list(range(N))
    rank = [0] * N

    def find(x: int):
        if parent[x]!= x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x: int, y: int):
        rootx = find(x)
        rooty = find(y)
        if rootx!= rooty:
            if rank[rootx] > rank[rooty]:
                parent[rooty] = rootx
            else:
                parent[rootx] = rooty
                if rank[rootx] == rank[rooty]:
                    rank[rooty] += 1

    for x, y in pairs:
        union(x, y)

    return len(set(find(x) for x in range(N)))
